body { font-family: system-ui, sans-serif; background: #eaf2fb; margin: 0; padding: 16px; }
.app { max-width: 420px; margin: 0 auto; background: white; padding: 20px; border-radius: 12px; }
h1 { margin-top: 0; color: #0b6fd6; }
form { display: flex; gap: 8px; }
input { flex: 1; padding: 8px; }
button { cursor: pointer; }
ul { list-style: none; padding: 0; }
li { display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #eee; }
li.done .text { text-decoration: line-through; color: gray; }
.text { cursor: pointer; flex: 1; }
.del { border: 0; background: transparent; color: tomato; font-size: 1.2rem; }

const form = document.getElementById("todo-form");
const input = document.getElementById("todo-input");
const list = document.getElementById("todo-list");

function addTodo(text) {
  const li = document.createElement("li");
  const span = document.createElement("span");
  span.className = "text";
  span.textContent = text;
  const del = document.createElement("button");
  del.className = "del";
  del.textContent = "×";
  li.append(span, del);
  list.appendChild(li);
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) return;            // bỏ qua việc rỗng
  addTodo(text);
  input.value = "";             // xoá ô nhập
});

list.addEventListener("click", (event) => {
  const li = event.target.closest("li");
  if (!li) return;
  if (event.target.classList.contains("del")) li.remove();       // xoá
  else if (event.target.classList.contains("text")) li.classList.toggle("done");  // hoàn thành
});

